style.css:
/* ==========================================================================
   小宝影视 · 影院模式
   用法：装 Stylish 扩展 → 新建样式 → 粘贴本文件 → 保存 → 勾选启用
   然后在播放页按 F11（浏览器全屏），播放器会铺满整个屏幕；
   跳下一集时 URL 变了、页面重载，但样式会自动重新生效，所以画面一直是铺满的。
   （纯 CSS，不改网站任何东西，只在你本机浏览器生效）
   ========================================================================== */

@media screen {

  /* 把播放器区域固定成整个视口 */
  #player-left {
    position: fixed !important;
    inset: 0 !important;
    z-index: 9998 !important;
    background: #000 !important;
    padding: 0 !important;
    margin: 0 !important;
    width: 100vw !important;
    max-width: 100vw !important;
    float: none !important;
  }

  /* 播放器外框：去掉 56.25% 的固定高宽比，改成撑满 */
  .myui-player__box,
  .myui-player__box .embed-responsive,
  .myui-player__box .embed-responsive .MacPlayer,
  .myui-player__box .MacPlayer {
    height: 100% !important;
    width: 100% !important;
    max-width: 100% !important;
    padding-bottom: 0 !important;
    float: none !important;
  }

  /* DPlayer 自身也要撑满（站点脚本给 .dplayer-video-wrap 写了内联 style，需要 !important 覆盖） */
  .myui-player__box .dplayer {
    height: 100% !important;
    width: 100% !important;
  }
  .myui-player__box .dplayer-video-wrap {
    position: absolute !important;
    inset: 0 !important;
    height: 100% !important;
    width: 100% !important;
    overflow: hidden !important;
  }
  .myui-player__box .dplayer-video {
    height: 100% !important;
    width: 100% !important;
    object-fit: contain !important;
  }

  /* 影院模式下隐藏页面里的次要元素 */
  .myui-player__box .tips,
  .myui-player__operate,
  #player-sidebar-is {
    display: none !important;
  }
}
